-- Inclusão somente: nunca sobrescreve planos ou fichas revisados. Sem alteração de contratos SFMC.
begin;

do $$ begin
 if (select count(*) from public.dynamic_email_briefings where campaign_group_id in ('0b4171aa-a7cf-417e-abfb-8485033ff125','09bf8951-fe4a-4a9e-b639-16b071fa1067') and briefing_data->'__editor'->>'kind'='vdv' and briefing_data->'__editor'->>'contentVersion'='BF26_V1' and partner='Afinz Visa' and week_key='Black Friday') <> 2 then
 raise exception 'Os dois documentos Visa BF26 não correspondem à fonte revisada. Conferir antes de cadastrar.';
 end if;
end $$;

